{"command":"cat <<'PY' > /tmp/server.py
import http.server, socketserver, sys, json
class H(http.server.BaseHTTPRequestHandler):
    def do_GET(self): self.handle_all()
    def do_POST(self): self.handle_all()
    def do_PUT(self): self.handle_all()
    def do_DELETE(self): self.handle_all()
    def do_PATCH(self): self.handle_all()
    def do_HEAD(self): self.handle_all()
    def do_OPTIONS(self): self.handle_all()
    def handle_all(self):
        length=int(self.headers.get('Content-Length') or 0)
        body=self.rfile.read(length) if length else b''
        info={"method":self.command,"path":self.path,"headers":list(self.headers.items()),"body":body.decode('utf-8', 'replace')}
        sys.stderr.write("SERVER GOT: "+json.dumps(info)+"\n"); sys.stderr.flush()
        # respond based on path
        if self.path.startswith("/json"):
            data=b'{"hello":"world","num":42,"arr":[1,2,3]}'
            self.send_response(200); self.send_header("Content-Type","application/json"); self.send_header("Content-Length",str(len(data))); self.end_headers(); self.wfile.write(data)
        elif self.path.startswith("/text"):
            data=b'hello text\nsecond line\n'
            self.send_response(200); self.send_header("Content-Type","text/plain"); self.send_header("Content-Length",str(len(data))); self.end_headers(); self.wfile.write(data)
        elif self.path.startswith("/status"):
            code=int(self.path.split("/")[2]) if len(self.path.split("/"))>2 else 200
            data=b'status body'
            self.send_response(code); self.send_header("Content-Type","text/plain"); self.send_header("Content-Length",str(len(data))); self.end_headers(); self.wfile.write(data)
        elif self.path.startswith("/echo"):
            data=json.dumps(info).encode()
            self.send_response(200); self.send_header("Content-Type","application/json"); self.send_header("Content-Length",str(len(data))); self.end_headers(); self.wfile.write(data)
        else:
            data=b'{"ok":true}'
            self.send_response(200); self.send_header("Content-Type","application/json"); self.send_header("Content-Length",str(len(data))); self.end_headers(); self.wfile.write(data)
    def log_message(self, format, *args):
        sys.stderr.write("LOG: %s\n" % (format%args)); sys.stderr.flush()
PORT=18080
httpd=socketserver.TCPServer(("127.0.0.1",PORT), H)
print(f"listening {PORT}", flush=True)
httpd.serve_forever()
PY
python3 /tmp/server.py 2>/tmp/server.log &
echo $! > /tmp/server.pid
sleep 1
cat /tmp/server.log
curl -s http://127.0.0.1:18080/json; echo
echo "--- curlie GET ---"
./executable http://127.0.0.1:18080/json; echo EXIT:$?
echo "--- server log ---"
cat /tmp/server.log
"}

