for ch in chars:
    a=["--curl",f"-{ch}","http://x"]
    o=out(a)
    # expected if retained: curl -{ch} http://x ...
    if o.startswith(f"curl -{ch} http://x") or o.startswith(f"curl -{ch} "):
        status="retained"
    elif o.startswith("curl http://x"):
        status="DROPPED"
    else:
        status="OTHER:"+o
    if status!="retained":
        print(ch, status)
print("done short before URL")
# long options list from curl help all
import subprocess, re
helpall=subprocess.run(["curl","--help","all"],capture_output=True,text=True).stdout
longs=[]
for line in helpall.splitlines():
    m=re.search(r'--([a-z0-9.\-]+)',line)
    if m: longs.append(m.group(1))
print("num longs",len(longs))
dropped=[]
other=[]
for lo in longs:
    a=["--curl",f"--{lo}","http://x"]
    o=out(a)
    if o.startswith(f"curl --{lo} http://x") or o.startswith(f"curl --{lo} "):
        pass
    elif o.startswith("curl http://x"):
        dropped.append(lo)
    else:
        other.append((lo,o))
print("dropped longs:",dropped)
print("other longs:",other[:50])
