package main
import ("fmt"; "net/url"; "os"; "strings")
func transform(raw string) (string,string) {
 s:=raw
 added:=false
 if !strings.HasPrefix(s,"http") {
   s="http://" + strings.TrimPrefix(s,"//")
   added=true
 }
 // stderr would be s
 u, err:=url.Parse(s)
 if err!=nil {
   fmt.Print(err) // to stdout per original? in proto we return as prefix
   return s, s
