# start server thread via harness imports (logs etc)
import harness
import os, pty, subprocess, select, time

def run_pty(args, stdin_is_tty=True, stdout_is_tty=True, stderr_is_tty=True, input_data=b""):
    fds={}
    masters={}
    slaves={}
    for name in ["out","err","in"]:
        m,s=pty.openpty()
        masters[name]=m; slaves[name]=s
    # configure stdin slave maybe?
    p=subprocess.Popen(["/workspace/executable"]+args, stdout=slaves["out"] if stdout_is_tty else subprocess.PIPE, stderr=slaves["err"] if stderr_is_tty else subprocess.PIPE, stdin=slaves["in"] if stdin_is_tty else subprocess.PIPE)
    os.close(slaves["out"]); os.close(slaves["err"]); os.close(slaves["in"])
    if not stdin_is_tty:
        pass
    out=b""; err=b""
    # read until exit using select on masters if tty else communicate
    if stdout_is_tty or stderr_is_tty:
        # set masters nonblocking?
        import fcntl
        for name in ["out","err"]:
            if (name=="out" and stdout_is_tty) or (name=="err" and stderr_is_tty):
                fcntl.fcntl(masters[name], fcntl.F_SETFL, os.O_NONBLOCK)
        while p.poll() is None:
            for name in ["out","err"]:
                if (name=="out" and not stdout_is_tty) or (name=="err" and not stderr_is_tty): continue
                try:
                    data=os.read(masters[name], 65536)
                    if data:
                        if name=="out": out+=data
                        else: err+=data
                except BlockingIOError:
                    pass
                except OSError:
                    pass
            time.sleep(0.02)
        # final drain
        time.sleep(0.1)
        for name in ["out","err"]:
            if (name=="out" and not stdout_is_tty) or (name=="err" and not stderr_is_tty): continue
            try:
                while True:
                    data=os.read(masters[name], 65536)
                    if not data: break
                    if name=="out": out+=data
                    else: err+=data
            except Exception:
                pass
        if not stdout_is_tty:
            out = p.stdout.read() if p.stdout else b""
        if not stderr_is_tty:
            err = p.stderr.read() if p.stderr else b""
    else:
        out,err=p.communicate(input=input_data)
    p.wait()
    for m in masters.values():
        try: os.close(m)
        except: pass
    print("ARGS",args,"tty_out",stdout_is_tty,"tty_err",stderr_is_tty,"tty_in",stdin_is_tty,"exit",p.returncode)
    print(" OUT",out)
    print(" ERR",err)
    print(" SERVER",harness.logs)
    print()
    harness.logs.clear()

