package main

import (
	"bytes"
	"io"
	"strings"
)

// ---------- JSON / body formatter ----------

const binaryNote = "+-----------------------------------------+\n| NOTE: binary data not shown in terminal |\n+-----------------------------------------+\n"

type jsonFormatter struct {
	w           io.Writer
	started     bool // first byte seen
	formatting  bool
	binary      bool
	depth       int
	inString    bool
	delim       byte
	prev        byte // previous input byte (escape detection)
	expectValue bool
	inScalar    bool
}

func newJSONFormatter(w io.Writer) *jsonFormatter {
	return &jsonFormatter{w: w}
}

func (f *jsonFormatter) Write(p []byte) (int, error) {
	if f.binary {
		return len(p), nil
	}
	if bytes.IndexByte(p, 0) >= 0 {
		f.binary = true
		io.WriteString(f.w, binaryNote)
		return len(p), nil
	}
	for _, b := range p {
		f.writeByte(b)
	}
	return len(p), nil
}

func (f *jsonFormatter) writeByte(b byte) {
	if !f.started {
		f.started = true
		if b == '{' || b == '[' {
			f.formatting = true
		} else {
			f.formatting = false
		}
	}
	if !f.formatting {
		f.w.Write([]byte{b})
		f.prev = b
		return
	}
	if f.inString {
		escaped := f.prev == '\\'
		switch {
		case b == f.delim && !escaped:
			f.w.Write([]byte{b})
			f.inString = false
		case (b == '"' || b == '\'') && b != f.delim && !escaped:
			// A quote of the other kind inside a string is dropped.
		default:
			f.w.Write([]byte{b})
		}
		f.prev = b
		return
	}
	switch b {
	case ' ', '\t', '\r', '\n':
		// whitespace between tokens is discarded
	case '{', '[':
		f.depth++
		io.WriteString(f.w, "\x1b[37m")
		f.w.Write([]byte{b})
		io.WriteString(f.w, "\n"+strings.Repeat("    ", f.depth))
		f.expectValue = false
		f.inScalar = false
	case '}', ']':
		f.depth--
		if f.depth < 0 {
			f.depth = 0
		}
		io.WriteString(f.w, "\n"+strings.Repeat("    ", f.depth))
		io.WriteString(f.w, "\x1b[37m")
		f.w.Write([]byte{b})
		if f.depth == 0 {
			io.WriteString(f.w, "\n\x1b[0m")
		}
		f.expectValue = false
		f.inScalar = false
	case ',':
		io.WriteString(f.w, "\x1b[37m,\n"+strings.Repeat("    ", f.depth))
		f.expectValue = false
		f.inScalar = false
	case ':':
		io.WriteString(f.w, "\x1b[37m: ")
		f.expectValue = true
		f.inScalar = false
	case '"', '\'':
		if f.expectValue {
			io.WriteString(f.w, "\x1b[36m")
		} else {
			io.WriteString(f.w, "\x1b[34m")
		}
		f.w.Write([]byte{b})
		f.inString = true
		f.delim = b
		f.inScalar = true
	default:
		if !f.inScalar {
			if f.expectValue {
				if b == 't' || b == 'f' || b == 'n' {
					io.WriteString(f.w, "\x1b[35m")
				} else {
					io.WriteString(f.w, "\x1b[36m")
				}
			}
			f.inScalar = true
		}
		f.w.Write([]byte{b})
	}
	f.prev = b
}

// ---------- usage-line replacement writer (help output) ----------

type usageReplaceWriter struct {
	w        io.Writer
	done     bool
	pending  []byte
	replaced bool
}

var usageNeedle = []byte("curl [options...] <url>")

func newUsageReplaceWriter(w io.Writer) *usageReplaceWriter {
	return &usageReplaceWriter{w: w}
}

func (u *usageReplaceWriter) replacement() []byte {
	return []byte(os.Args[0] + " [options...] [METHOD] URL [REQUEST_ITEM [REQUEST_ITEM ...]]")
}

func (u *usageReplaceWriter) Write(p []byte) (int, error) {
	if u.replaced {
		_, err := u.w.Write(p)
		return len(p), err
	}
	data := append(append([]byte{}, u.pending...), p...)
	idx := bytes.Index(data, usageNeedle)
	if idx >= 0 {
		out := append([]byte{}, data[:idx]...)
		out = append(out, u.replacement()...)
		out = append(out, data[idx+len(usageNeedle):]...)
		_, err := u.w.Write(out)
		u.pending = nil
		u.replaced = true
		return len(p), err
	}
	// Keep only a tail that could be the start of the needle.
	keep := len(usageNeedle) - 1
	if len(data) > keep {
		flush := data[:len(data)-keep]
		if _, err := u.w.Write(flush); err != nil {
			return len(p), err
		}
		u.pending = append([]byte{}, data[len(data)-keep:]...)
	} else {
		u.pending = data
	}
	return len(p), nil
}

func (u *usageReplaceWriter) Flush() {
	if len(u.pending) > 0 && !u.replaced {
		u.w.Write(u.pending)
		u.pending = nil
	}
}
