package main

import (
	"io"
	"strings"
)

type headerWriter struct {
	w        io.Writer
	verbose  bool
	color    bool
	buf      []byte
	dataSeen bool
}

func newHeaderWriter(w io.Writer, verbose, color bool) *headerWriter {
	return &headerWriter{w: w, verbose: verbose, color: color}
}

func (h *headerWriter) Write(p []byte) (int, error) {
	for _, b := range p {
		if b == '\n' {
			h.processLine(string(h.buf))
			h.buf = h.buf[:0]
		} else {
			h.buf = append(h.buf, b)
		}
	}
	return len(p), nil
}

func (h *headerWriter) processLine(line string) {
	if line == "" {
		io.WriteString(h.w, "\n")
		return
	}
	switch line[0] {
	case '<':
		if len(line) == 1 {
			return
		}
		io.WriteString(h.w, formatLine(line[2:], h.color)+"\n")
	case '>':
		if !h.verbose {
			return
		}
		if len(line) == 1 {
			return
		}
		io.WriteString(h.w, formatLine(line[2:], h.color)+"\n")
	case '*':
		if !h.verbose {
			return
		}
		if h.color && strings.HasPrefix(line, "* ") {
			io.WriteString(h.w, "\x1b[90m"+line+"\x1b[0m\n")
		} else {
			io.WriteString(h.w, line+"\n")
		}
	case '{', '}':
		if !h.verbose {
			return
		}
		if !h.dataSeen {
			h.dataSeen = true
			io.WriteString(h.w, "\n\n")
		}
	default:
		io.WriteString(h.w, formatLine(line, h.color)+"\n")
	}
}

func isSpaceByte(b byte) bool {
	return b == ' ' || b == '\t' || b == '\r' || b == '\n' || b == '\f' || b == '\v'
}
func isDigitDot(b byte) bool { return (b >= '0' && b <= '9') || b == '.' }
func isDigit(b byte) bool     { return b >= '0' && b <= '9' }

func formatLine(line string, color bool) string {
	if !color {
		return line
	}
	// Response status line: HTTP/<version> <code><reason>
	if strings.HasPrefix(line, "HTTP/") {
		rest := line[5:]
		i := 0
		for i < len(rest) && isDigitDot(rest[i]) {
			i++
		}
		if i > 0 {
			j := i
			for j < len(rest) && isSpaceByte(rest[j]) {
				j++
			}
			if j > i && j+3 <= len(rest) && isDigit(rest[j]) && isDigit(rest[j+1]) && isDigit(rest[j+2]) {
				after := j + 3
				if len(line[5+after:]) >= 0 {
					rem := line[5+after:]
					if len(rem) >= 2 && isSpaceByte(rem[0]) {
						return "\x1b[34mHTTP\x1b[37m/\x1b[36m" + line[5:5+after] + "\x1b[33m" + rem + "\x1b[0m"
					}
				}
			}
		}
	}
	// Request line: METHOD <target> HTTP/<version>
	{
		i := 0
		for i < len(line) && line[i] >= 'A' && line[i] <= 'Z' {
			i++
		}
		if i > 0 {
			// whitespace, path, whitespace
			j := i
			for j < len(line) && isSpaceByte(line[j]) {
				j++
			}
			if j > i {
				k := j
				for k < len(line) && !isSpaceByte(line[k]) {
					k++
				}
				if k > j {
					m := k
					for m < len(line) && isSpaceByte(line[m]) {
						m++
					}
					if m > k && strings.HasPrefix(line[m:], "HTTP/") {
						ver := line[m+5:]
						n := 0
						for n < len(ver) && isDigitDot(ver[n]) {
							n++
						}
						if n > 0 {
							tail := ver[n:]
							tailOK := true
							for t := 0; t < len(tail); t++ {
								if !isSpaceByte(tail[t]) {
									tailOK = false
									break
								}
							}
							if tailOK {
								return "\x1b[34m" + line[:i] + "\x1b[37m" + line[i:m] + "\x1b[34mHTTP\x1b[37m/\x1b[36m" + ver + "\x1b[0m"
							}
						}
					}
				}
			}
		}
	}
	// Curl errors such as "curl: (6) ..."
	if strings.HasPrefix(line, "curl: (") {
		rest := line[7:]
		i := 0
		for i < len(rest) && isDigit(rest[i]) {
			i++
		}
		if i > 0 && i < len(rest) && rest[i] == ')' {
			return "\x1b[31m" + line + "\x1b[0m"
		}
	}
	// Ordinary headers: Name: value
	if idx := strings.Index(line, ":"); idx >= 0 {
		name := line[:idx]
		ok := true
		for i := 0; i < len(name); i++ {
			c := name[i]
			if !(c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '.' || c == '-') {
				ok = false
				break
			}
		}
		if ok {
			return "\x1b[37m" + line[:idx+1] + "\x1b[36m" + line[idx+1:] + "\x1b[0m"
		}
	}
	return line
}
