package main

import (
	"bytes"
	"sync"
)

// stdinCapture wraps stdin, remembering everything read through it so
// the request body can be shown in verbose output.
type stdinCapture struct {
	r   interface{ Read([]byte) (int, error) }
	mu  sync.Mutex
	buf bytes.Buffer
}

func (c *stdinCapture) Read(p []byte) (int, error) {
	n, err := c.r.Read(p)
	if n > 0 {
		c.mu.Lock()
		c.buf.Write(p[:n])
		c.mu.Unlock()
	}
	return n, err
}

func (c *stdinCapture) snapshot() string {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.buf.String()
}
